use vstd::prelude::*;

verus! {

spec fn inserted_before_each(arr: Seq<i32>, elem: i32) -> Seq<i32>
    decreases arr.len(),
{
    if arr.len() == 0 {
        Seq::<i32>::empty()
    } else {
        seq![elem, arr[0]] + inserted_before_each(arr.drop_first(), elem)
    }
}

fn insert_before_each(arr: &Vec<i32>, elem: i32) -> (result: Vec<i32>)
    ensures
        result@ == inserted_before_each(arr@, elem),
        result@.len() == 2 * arr@.len(),
{
    let mut result = Vec::with_capacity(arr.len() * 2);

    for &x in arr.iter()
        invariant
            result@ == inserted_before_each(arr@.take(result@.len() / 2), elem),
            result@.len() % 2 == 0,
            result@.len() <= 2 * arr@.len(),
            // capacity-related fact (not required for correctness, but helps with arithmetic):
            arr@.len() * 2 == 2 * arr@.len(),
        ensures
            result@ == inserted_before_each(arr@, elem),
            result@.len() == 2 * arr@.len(),
    {
        result.push(elem);
        result.push(x);

        // After pushing two elements, the result corresponds to one more processed input element.
        assert(result@.len() % 2 == 0);
        assert(result@.len() / 2 <= arr@.len());
        assert(arr@.take(result@.len() / 2)
            == arr@.take((result@.len() / 2 - 1)).push(x));
    }

    result
}

} // verus!

